import com.fasterxml.jackson.databind.*;

public class Main {
    public static void main(String[] args) throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        Todo t = new Todo(1, "Belajar JSON", false);
        System.out.println(mapper.writeValueAsString(t));

        t.setCatatan("bab 1 sampai 3");
        System.out.println(mapper.writeValueAsString(t));

        Todo dibaca = mapper.readValue("{\"id\":2,\"judul\":\"Beli kopi\",\"selesai\":true}", Todo.class);
        System.out.println(dibaca.getLabel() + " " + dibaca.isSelesai());
    }
}

